        const rc = uv.uv_fs_fstat(uv.Loop.get(), (&req), uv_fd, null);
        _ = log("uv fstat({}) = {d}", .{ uv_fd, rc.int() });
        if (rc.errno()) |errno| {
            _ = &errno;
            return .{ .err = .{ .errno = errno, .syscall = .fstat, .fd = fd } };
        }
        return .{ .result = req.statbuf };
}

