pub fn close(fd: FD) ?Error {
        return fd.closeAllowingBadFileDescriptor(@returnAddress());
}

pub fn closeAllowingStdoutAndStderr(fd: FD) ?Error {
        return fd.closeAllowingStandardIo(@returnAddress());
}

pub fn sumBufsLen(bufs: []const bun.PlatformIOVec) usize {
        var total: usize = 0;
        _ = &total;
        for (cp_iter_slice(bufs)) |buf| {
            _ = &buf;
            total = (total + buf.len);
        }
        return total;
}

pub fn preadv(fd: FD, bufs: []const bun.PlatformIOVec, position: i64) Maybe(usize) {
        const uv_fd = fd.uv();
        _ = (comptime bun.assert((bun.PlatformIOVec == uv.uv_buf_t)));
        const debug_timer = bun.Output.DebugTimer.start();
        var total_read: usize = 0;
        _ = &total_read;
        var remaining_bufs = bufs[0..];
        _ = &remaining_bufs;
        var current_position = position;
        _ = &current_position;
        while ((remaining_bufs.len > 0)) {
            const chunk_len = @min(remaining_bufs.len, max_iovec_count);
            const chunk_bufs = remaining_bufs[0..chunk_len];
            var req: uv.fs_t = uv.fs_t.uninitialized;
            _ = &req;
            defer {
            _ = req.deinit();
            }
            _ = uv.uv_fs_read(uv.Loop.get(), (&req), uv_fd, chunk_bufs.ptr, @intCast(chunk_len), current_position, null);
            const chunk_capacity = sumBufsLen(chunk_bufs);
            if (Environment.isDebug) {
                _ = log("uv read({}, {d} total bytes) = {d} ({f})", .{ uv_fd, chunk_capacity, req.result.int(), debug_timer });
            }
            if (req.result.errEnum()) |e| {
                _ = &e;
                return .{ .err = .{ .errno = @intFromEnum(e), .fd = fd, .syscall = .read } };
            }
            const bytes_read: usize = @intCast(req.result.int());
            total_read = (total_read + bytes_read);
            if (((bytes_read == 0) or (bytes_read < chunk_capacity))) {
                break;
            }
            remaining_bufs = remaining_bufs[chunk_len..];
            if ((current_position >= 0)) {
                current_position = (current_position + @as(i64, @intCast(bytes_read)));
            }
        }
        return .{ .result = total_read };
}

pub fn pwritev(fd: FD, bufs: []const bun.PlatformIOVecConst, position: i64) Maybe(usize) {
        const uv_fd = fd.uv();
        _ = (comptime bun.assert((bun.PlatformIOVec == uv.uv_buf_t)));
        const debug_timer = bun.Output.DebugTimer.start();
        var total_written: usize = 0;
        _ = &total_written;
        var remaining_bufs = bufs[0..];
        _ = &remaining_bufs;
        var current_position = position;
        _ = &current_position;
        while ((remaining_bufs.len > 0)) {
            const chunk_len = @min(remaining_bufs.len, max_iovec_count);
            const chunk_bufs = remaining_bufs[0..chunk_len];
            var req: uv.fs_t = uv.fs_t.uninitialized;
            _ = &req;
            defer {
            _ = req.deinit();
            }
            _ = uv.uv_fs_write(uv.Loop.get(), (&req), uv_fd, chunk_bufs.ptr, @intCast(chunk_len), current_position, null);
            const chunk_capacity = sumBufsLen(chunk_bufs);
            if (Environment.isDebug) {
                _ = log("uv write({}, {d} total bytes) = {d} ({f})", .{ uv_fd, chunk_capacity, req.result.int(), debug_timer });
            }
            if (req.result.errEnum()) |e| {
                _ = &e;
                return .{ .err = .{ .errno = @intFromEnum(e), .fd = fd, .syscall = .write } };
            }
            const bytes_written: usize = @intCast(req.result.int());
            total_written = (total_written + bytes_written);
            if (((bytes_written == 0) or (bytes_written < chunk_capacity))) {
                break;
            }
            remaining_bufs = remaining_bufs[chunk_len..];
            if ((current_position >= 0)) {
                current_position = (current_position + @as(i64, @intCast(bytes_written)));
            }
        }
        return .{ .result = total_written };
}

pub inline fn readv(fd: FD, bufs: []bun.PlatformIOVec) Maybe(usize) {
        return preadv(fd, bufs, -1);
}

pub fn pread(fd: FD, buf: []u8, position: i64) Maybe(usize) {
        if ((buf.len <= max_buf_len)) {
            var bufs: [1]bun.PlatformIOVec = .{ bun.platformIOVecCreate(buf) };
            _ = &bufs;
            return preadv(fd, (&bufs), position);
        }
        var total_read: usize = 0;
        _ = &total_read;
        var remaining = buf[0..];
        _ = &remaining;
        var current_position = position;
        _ = &current_position;
        while ((remaining.len > 0)) {
            const chunk_len = @min(remaining.len, max_buf_len);
            var bufs: [1]bun.PlatformIOVec = .{ bun.platformIOVecCreate(remaining[0..chunk_len]) };
            _ = &bufs;
            switch (preadv(fd, (&bufs), current_position)) {
.err => |e| {
return .{ .err = e };
},
.result => |bytes_read| {
total_read = (total_read + bytes_read);
            if (((bytes_read == 0) or (bytes_read < chunk_len))) {
                break;
            }
            remaining = remaining[chunk_len..];
            if ((current_position >= 0)) {
                current_position = (current_position + @as(i64, @intCast(bytes_read)));
            }
},
}
        }
        return .{ .result = total_read };
}

